import numpy as np
from ucminf import ucminf

def fR(x):
    return (1 - x[0]) ** 2 + 100 * (x[1] - x[0] ** 2) ** 2

def gR(x):
    return np.array([
        -400 * x[0] * (x[1] - x[0] * x[0]) - 2 * (1 - x[0]),
        200 * (x[1] - x[0] * x[0]),
    ])

print(ucminf(np.array([2.0, 0.5]), fR, gR))
